/// Per-country IBAN layout from the SWIFT IBAN Registry.
///
/// The data lives in `iban_registry.g.dart`, generated by
/// `tool/generate_iban_registry.dart`.
library;

export 'iban_registry.g.dart';

/// One country's IBAN layout as published in the SWIFT IBAN Registry.
///
/// Offsets are 0-based and end-exclusive within the whole IBAN (country
/// code and check digits included), matching [String.substring].
class IbanRegistryEntry {
  /// Exact length of the country's electronic-format IBAN.
  final int ibanLength;

  /// The BBAN in ISO 13616 notation, e.g. `5!n11!n`: `n` is a digit, `a`
  /// an upper-case letter and `c` either, each prefixed by its length.
  final String bbanFormat;

  final int bankCodeStart;
  final int bankCodeEnd;
  final int? branchCodeStart;
  final int? branchCodeEnd;

  /// The registry's sample IBAN for the country.
  final String example;

  const IbanRegistryEntry({
    required this.ibanLength,
    required this.bbanFormat,
    required this.bankCodeStart,
    required this.bankCodeEnd,
    this.branchCodeStart,
    this.branchCodeEnd,
    required this.example,
  });

  /// Whether [bban] (the IBAN without its first four characters) has the
  /// character classes [bbanFormat] prescribes, position by position.
  bool matchesBban(String bban) {
    int pos = 0;
    int count = 0;
    for (int i = 0; i < bbanFormat.length; i++) {
      final int f = bbanFormat.codeUnitAt(i);
      if (f >= 0x30 && f <= 0x39) {
        count = count * 10 + (f - 0x30);
      } else if (f == 0x21) {
        // '!' marks a fixed length; the registry uses nothing else.
      } else {
        if (pos + count > bban.length) return false;
        for (int j = pos; j < pos + count; j++) {
          if (!_matches(f, bban.codeUnitAt(j))) return false;
        }
        pos += count;
        count = 0;
      }
    }
    return pos == bban.length;
  }

  static bool _matches(int kind, int c) {
    final bool digit = c >= 0x30 && c <= 0x39;
    final bool upper = c >= 0x41 && c <= 0x5A;
    return switch (kind) {
      0x6E => digit, // n
      0x61 => upper, // a
      _ => digit || upper, // c
    };
  }
}
